import 'package:flutter/material.dart';

import '../theme/app_theme.dart';
import '../theme/tokens.g.dart';

/// The Gleefy mark: the phone in a party hat from the app icon (assets/brand/mark.png, generated by
/// scripts/brand-icons.mjs from the same drawing).
class GleefyMark extends StatelessWidget {
  const GleefyMark({super.key, this.size = 40});

  final double size;

  @override
  Widget build(BuildContext context) => ExcludeSemantics(
    child: Image.asset('assets/brand/mark.png', height: size, filterQuality: FilterQuality.medium),
  );
}

class GleefyWordmark extends StatelessWidget {
  const GleefyWordmark({super.key, this.size = 28, this.premium = false});

  final double size;

  /// Adds a small gold "PREMIUM" tag after the name, like a subscription badge on a logo.
  final bool premium;

  @override
  Widget build(BuildContext context) {
    return Semantics(
      header: true,
      label: premium ? 'Gleefy Premium' : 'Gleefy',
      child: ExcludeSemantics(
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            GleefyMark(size: size * 1.2),
            const SizedBox(width: GfSpace.s2),
            Text(
              'Gleefy',
              style: TextStyle(fontFamily: GfFont.display, fontWeight: FontWeight.w700, fontSize: size),
            ),
            if (premium) ...[const SizedBox(width: GfSpace.s2), const PremiumTag()],
          ],
        ),
      ),
    );
  }
}

/// A round avatar with the account's initial, for the home screen's app bar. A gold ring marks
/// Premium. Shown only when signed in, so free play never nudges anyone to make an account.
class AccountAvatarButton extends StatelessWidget {
  const AccountAvatarButton({
    super.key,
    required this.email,
    required this.premium,
    required this.onPressed,
    required this.tooltip,
  });

  final String? email;
  final bool premium;
  final VoidCallback onPressed;
  final String tooltip;

  static String initialOf(String? email) {
    final text = email?.trim() ?? '';
    return text.isEmpty ? '?' : text.characters.first.toUpperCase();
  }

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    return IconButton(
      tooltip: tooltip,
      onPressed: onPressed,
      icon: Container(
        width: 34,
        height: 34,
        alignment: Alignment.center,
        decoration: BoxDecoration(
          shape: BoxShape.circle,
          color: scheme.primary,
          border: premium ? Border.all(color: const Color(0xFFFFB020), width: 3) : null,
        ),
        child: Text(
          initialOf(email),
          style: TextStyle(
            color: scheme.onPrimary,
            fontFamily: GfFont.display,
            fontWeight: FontWeight.w700,
            fontSize: 16,
          ),
        ),
      ),
    );
  }
}

/// The gold "PREMIUM" tag shown once the account has Premium (same colours as the website's).
class PremiumTag extends StatelessWidget {
  const PremiumTag({super.key});

  @override
  Widget build(BuildContext context) => DecoratedBox(
    decoration: BoxDecoration(
      gradient: const LinearGradient(colors: [Color(0xFFFFD34D), Color(0xFFFFAE2B)]),
      borderRadius: BorderRadius.circular(6),
    ),
    child: const Padding(
      padding: EdgeInsets.symmetric(horizontal: 7, vertical: 2),
      child: Text(
        'PREMIUM',
        style: TextStyle(color: Color(0xFF3B2400), fontSize: 11, fontWeight: FontWeight.w900, letterSpacing: 0.7),
      ),
    ),
  );
}

/// A rounded card filled with the brand gradient. Text on it is white (contrast tested in tokens).
class GradientPanel extends StatelessWidget {
  const GradientPanel({super.key, required this.child, this.onTap, this.padding = const EdgeInsets.all(GfSpace.s6)});

  final Widget child;
  final VoidCallback? onTap;
  final EdgeInsets padding;

  @override
  Widget build(BuildContext context) {
    return DecoratedBox(
      decoration: BoxDecoration(
        gradient: GfPalette.of(context).gradient,
        borderRadius: BorderRadius.circular(GfRadius.xl),
      ),
      child: Material(
        type: MaterialType.transparency,
        child: InkWell(
          borderRadius: BorderRadius.circular(GfRadius.xl),
          onTap: onTap,
          child: Padding(
            padding: padding,
            child: DefaultTextStyle.merge(
              style: const TextStyle(color: Colors.white),
              child: IconTheme.merge(
                data: const IconThemeData(color: Colors.white),
                child: child,
              ),
            ),
          ),
        ),
      ),
    );
  }
}
